(()=>{var r=()=>{let e=document.querySelector(".com-unordered"),o=document.querySelector("#right-arrow"),l=document.querySelector("#left-arrow");e.scrollLeft+e.offsetWidth<e.scrollWidth&&o.classList.remove("hlp-none"),document.querySelector("#right-arrow").addEventListener("click",()=>{let t=e.scrollLeft+150;e.scroll({left:t,behavior:"smooth"}),e.scrollLeft+e.offsetWidth>=e.scrollWidth&&o.classList.add("hlp-none"),l.classList.remove("hlp-none")}),document.querySelector("#left-arrow").addEventListener("click",()=>{let t=e.scrollLeft-150;e.scroll({left:t,behavior:"smooth"}),e.scrollLeft===0&&l.classList.add("hlp-none"),o.classList.remove("hlp-none")})};r();})();
